test("fields with delimiters, quotes and line breaks stay in one column",()=>{
  assert.equal(exportContacts([{id:"c3",name:"Doe, Jane",company:"Acme, Inc",email:"jane@example.test"}]),"id,name,company,email\r\nc3,\"Doe, Jane\",\"Acme, Inc\",jane@example.test\r\n");
  assert.equal(exportContacts([{id:"c4",name:"Jane \"JD\" Doe",company:"Line1\nLine2",email:"a\r\nb"}]),"id,name,company,email\r\nc4,\"Jane \"\"JD\"\" Doe\",\"Line1\nLine2\",\"a\r\nb\"\r\n");
  assert.equal(exportContacts([{id:"c5",name:"=SUM(A1,B1)",company:"Acme",email:""}]),"id,name,company,email\r\nc5,\"'=SUM(A1,B1)\",Acme,\r\n");
});
EOF
